function normalizeRoutingText(value = "") {
  return String(value || "").normalize("NFKC").toLowerCase();
}

function hasHorizontalCanvasSignal(text = "") {
  const value = normalizeRoutingText(text);
  return /(?:16\s*:\s*9|1920\s*x\s*1080|landscape|horizontal|横屏|横版|local-review-horizontal)/i.test(value);
}

function hasNegatedVerticalSignal(text = "") {
  const value = normalizeRoutingText(text);
  return /(?:不|非|不是|不要|无需|不做|别做|并非|没有|未要求|未指定|无须).{0,10}(?:竖屏|竖版|竖向|短视频)|not\s+(?:a\s+)?(?:vertical|portrait|short[-\s]?form|short\s+video|youtube\s+shorts?|tiktok|tik\s*tok|reels)/i.test(value);
}

function hasExplicitVerticalShortFormSignal(text = "") {
  const value = normalizeRoutingText(text);
  if (!value || hasNegatedVerticalSignal(value)) return false;
  return /(?:9\s*:\s*16|1080\s*x\s*1920|portrait|vertical|竖屏|竖版|竖向|抖音|douyin|快手|kuaishou|tiktok|tik\s*tok|youtube\s+shorts?|shorts\b|reels\b|short[-\s]?form|short\s+video|短视频)/i.test(value);
}

function briefHasExplicitVerticalShortFormIntent(brief = {}) {
  const canvas = brief.canvas || {};
  if (Number(canvas.width || 0) > 0 && Number(canvas.height || 0) > 0) {
    return Number(canvas.height) > Number(canvas.width);
  }
  const aspectText = [
    brief.aspectRatio,
    brief.aspect,
    brief.ratio,
    brief.canvasAspect,
    brief.resolution,
  ].filter(Boolean).join(" ");
  if (hasHorizontalCanvasSignal(aspectText)) return false;
  if (hasExplicitVerticalShortFormSignal(aspectText)) return true;

  const platformText = [
    brief.platform,
    brief.platformProfile,
    brief.targetPlatform,
    brief.outputPlatform,
    brief.channel,
    brief.format,
    brief.orientation,
  ].filter(Boolean).join(" ");
  if (hasHorizontalCanvasSignal(platformText) && !hasExplicitVerticalShortFormSignal(platformText)) return false;
  if (hasExplicitVerticalShortFormSignal(platformText)) return true;

  const requestText = [
    brief.title,
    brief.objective,
    brief.contentMode,
    brief.deliveryFormat,
    brief.videoFormat,
  ].filter(Boolean).join(" ");
  return hasExplicitVerticalShortFormSignal(requestText);
}

function canvasForBrief(brief = {}) {
  const canvas = brief.canvas || {};
  if (Number(canvas.width || 0) > 0 && Number(canvas.height || 0) > 0) {
    const width = Number(canvas.width);
    const height = Number(canvas.height);
    const vertical = height > width;
    return {
      width,
      height,
      aspect: canvas.aspect || aspectRatio(width, height),
      vertical,
      platformProfile: canvas.platformProfile || (vertical ? "short-form-vertical" : "local-review-horizontal"),
    };
  }
  const vertical = briefHasExplicitVerticalShortFormIntent(brief);
  return vertical
    ? { width: 1080, height: 1920, aspect: "9:16", vertical: true, platformProfile: "short-form-vertical" }
    : { width: 1920, height: 1080, aspect: "16:9", vertical: false, platformProfile: "local-review-horizontal" };
}

function coverFileForCanvas(canvas) {
  return `cover/cover-video-opening-${canvas.aspect.replace(":", "x")}.svg`;
}

function safeFileStem(value, fallback = "video") {
  const cleaned = String(value || fallback)
    .normalize("NFKC")
    .replace(/[\\/:*?"<>|#%{}^~[\]`]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 80)
    .trim();
  return cleaned || fallback;
}

