function colorSystemTextFromBrief(brief = {}, frames = []) {
  return [
    brief.title,
    brief.objective,
    brief.audience,
    brief.platform,
    brief.style,
    brief.visualStyle,
    brief.topic,
    narrationTextFromBrief(brief.narration || "").slice(0, 900),
    ...frames.flatMap((frame) => [
      frame.id,
      frame.label,
      ...(Array.isArray(frame.headline) ? frame.headline : [frame.headline]),
      frame.body,
      frame.subtitle,
      frame.visualMode,
      frame.diagramMode,
    ]),
  ].filter(Boolean).join(" ");
}

function colorSystemHasNearBlack(system = {}) {
  return (system.colors || []).some((color) => {
    const rgb = colorToRgb(color);
    return rgb && rgb.r <= 38 && rgb.g <= 38 && rgb.b <= 38;
  });
}

function scoreColorSystem(system, { brief = {}, frames = [], videoType = "", styleProfile = {} } = {}) {
  const text = colorSystemTextFromBrief(brief, frames);
  const normalized = text.toLowerCase();
  let score = stableIndex(`${system.id}|${brief.title || ""}|${brief.objective || ""}`, 7);
  const reasons = [];
  for (const keyword of system.keywords || []) {
    if (keyword && normalized.includes(String(keyword).toLowerCase())) {
      score += 12;
      reasons.push(`命中内容关键词：${keyword}`);
    }
  }
  if (/personal-ip|creator|个人|口播|主讲|人设|ip/i.test(`${videoType} ${styleProfile.id || ""} ${text}`) && /creator|persona|ip/.test(system.id)) {
    score += 22;
    reasons.push("内容包含个人 IP/口播信号，优先人物友好的演播色系");
  }
  if (/whiteboard|sketch|formula|白板|手绘|公式|推导/i.test(`${videoType} ${text}`) && /whiteboard|sage|clear/.test(system.id)) {
    score += 20;
    reasons.push("内容需要白板/手绘/推导，优先低噪音浅底色系");
  }
  if (/data|chart|metric|dashboard|数据|图表|指标|趋势/i.test(`${videoType} ${text}`) && /newsprint|blue|data/.test(system.id)) {
    score += 18;
    reasons.push("内容包含数据/图表/趋势，优先可信的数据表达色系");
  }
  if (/tool|workflow|screen|product|saas|app|工具|产品|界面|流程/i.test(`${videoType} ${text}`) && /glass|product|ui|cool/.test(system.id)) {
    score += 16;
    reasons.push("内容包含工具/产品/流程，优先产品界面色系");
  }
  if (system.paletteMode === "mono" && /长|课程|教程|推导|whiteboard|lesson|course|tutorial/i.test(text)) {
    score += 8;
    reasons.push("长讲解或课程内容适合单色低疲劳体系");
  }
  const darkAllowed = darkStyleExplicitlyRequested(brief) || darkStageExplicitlyAllowed(brief, {});
  if (system.requiresExplicitDark && !darkAllowed) {
    score -= 80;
    reasons.push("未显式要求深色/纯黑，自动模式避免黑场色系");
  }
  if (!system.requiresExplicitDark && !colorSystemHasNearBlack(system)) {
    score += 4;
    reasons.push("无黑色锚点，适合默认自动推荐");
  }
  return { score, reasons };
}

function buildColorSystemPlan({ brief = {}, frames = [], videoType = "", styleProfile = {} } = {}) {
  const ranked = COLOR_SYSTEM_CATALOG.map((system) => {
    const scored = scoreColorSystem(system, { brief, frames, videoType, styleProfile });
    return { ...system, ...scored, hasBlack: colorSystemHasNearBlack(system) };
  }).sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));
  const selected = ranked[0] || COLOR_SYSTEM_CATALOG[0];
  const sceneBindings = frames.map((frame, index) => ({
    sceneId: frame.id || `scene-${index + 1}`,
    order: index + 1,
    selectedSystemId: selected.id,
    selectedPaletteName: selected.paletteNames[index % Math.max(1, selected.paletteNames.length)],
    elementUsage: {
      background: selected.colors[0],
      ink: selected.colors[1],
      accent: selected.colors[2] || palettes[selected.paletteNames[0]]?.accent || palettes.blue.accent,
      secondaryAccent: selected.colors[3] || palettes[selected.paletteNames[1]]?.accent || palettes.green.accent,
      container: selected.colors[4] || selected.colors[0],
    },
  }));
  return {
    schemaVersion: 1,
    status: "auto-color-system-plan",
    mode: "auto-by-default",
    sourceCatalog: "semi-auto-config colorSystems",
    plannerOwner: "codex-video-workflow planner",
    selectedSystem: {
      id: selected.id,
      label: selected.label,
      paletteMode: selected.paletteMode,
      role: selected.role,
      mood: selected.mood,
      themeKey: selected.themeKey,
      paletteNames: selected.paletteNames,
      colors: selected.colors,
      hasBlack: selected.hasBlack,
      score: selected.score,
      reasons: selected.reasons.length ? selected.reasons : ["按题材、口播和页面内容进行稳定哈希兜底选择"],
    },
    rankedCandidates: ranked.slice(0, 8).map((system) => ({
      id: system.id,
      label: system.label,
      paletteMode: system.paletteMode,
      score: system.score,
      reasons: system.reasons.slice(0, 4),
      rejectedForAuto: system.requiresExplicitDark && !(darkStyleExplicitlyRequested(brief) || darkStageExplicitlyAllowed(brief, {})),
    })),
    sceneBindings,
    appliedToVideoElements: [
      "visualTheme/background",
      "stage surface and container fills",
      "accent lines, arrows, highlights, and chart/formula/code states",
      "caption keyword highlight accent",
      "cover continuity and first-frame promise",
      "personal IP / whiteboard foreground components when active",
    ],
    userOverridePolicy: {
      autoEnabledByDefault: true,
      userMayOverride: true,
      overrideScope: "whole-video first; page-level override only through page TDS review",
      guardrails: [
        "未显式要求时不自动选择纯黑/深色体系",
        "色系必须写入 design-plan 和 quality-consistency-contract",
        "生成图片提示词和 HTML 动效元素必须引用同一套色系语义",
      ],
    },
  };
}

function paletteOrderForBrief(brief) {
  const colorSystemPlan = buildColorSystemPlan({ brief });
  const plannedPaletteNames = colorSystemPlan.selectedSystem?.paletteNames || [];
  if (plannedPaletteNames.length) return plannedPaletteNames;
  const names = Object.keys(palettes);
  const seed = `${brief?.title || ""}|${brief?.objective || ""}|${brief?.audience || ""}|${narrationTextFromBrief(brief?.narration || "").slice(0, 500)}`;
  const offset = stableIndex(seed || "codex-video-workflow", names.length);
  const rotated = names.slice(offset).concat(names.slice(0, offset));
  const rotateFamily = (family) => {
    const familyOffset = stableIndex(`${seed}|palette-family`, family.length);
    const familyRotated = family.slice(familyOffset).concat(family.slice(0, familyOffset));
    return [...familyRotated, ...rotated].filter((value, index, list) => list.indexOf(value) === index);
  };
  const text = seed;
  if (/金融|商业|投资|market|finance|business/i.test(text)) return rotateFamily(["blue", "green", "gold", "ink"]);
  if (/小说|写作|网文|故事|story|novel|writing/i.test(text)) return rotateFamily(["red", "purple", "ink", "gold", "blue"]);
  if (/学校|校园|学生|老师|教师|课堂|课程|教材|学习|教育|school|education|classroom|teacher|student|lesson|course/i.test(text)) return rotateFamily(["teal", "blue", "green", "cyan", "gold"]);
  if (/科技|AI|数据|软件|系统|tech|data|software|ai/i.test(text)) return rotateFamily(["cyan", "blue", "teal", "purple", "ink"]);
  if (/情感|关系|生活|心理|relationship|life|psychology/i.test(text)) return rotateFamily(["magenta", "purple", "gold", "teal", "ink"]);
  return rotated;
}

function paletteHexSet(names, themeKey = "storyPaper") {
  const theme = visualThemeForKey(themeKey);
  const base = [theme.ink, theme.background, theme.surface];
  return [...base, ...names.map((name) => palettes[name]?.accent).filter(Boolean)].slice(0, 8);
}

function estimateAutoDuration({ narration, frames, brief }) {
  const text = String(narration || "").trim();
  const zhChars = (text.match(/[\u3400-\u9fff]/g) || []).length;
  const nonZh = text.replace(/[\u3400-\u9fff\s]/g, "").length;
  const words = text.split(/\s+/).filter(Boolean).length;
  const speechSeconds = zhChars
    ? zhChars / 4.1 + nonZh / 8
    : words / 2.45;
  const sceneSeconds = Math.max(0, (frames?.length || 0) * 1.2);
  const requestedDepth = /(完整|详细|深入|教程|历史|long|complete|detailed|deep|tutorial|history)/i.test(`${brief?.title || ""} ${brief?.objective || ""} ${brief?.goal || ""}`)
    ? 10
    : 0;
  return clampDuration(Math.ceil((speechSeconds + sceneSeconds + requestedDepth + 4) / 5) * 5);
}

function textCharCount(value) {
  return String(value || "").replace(/\s+/g, "").length;
}

function readSourceMaterialPath(pathValue) {
  const value = String(pathValue || "").trim();
  if (!value) return "";
  const absolutePath = resolve(ROOT, value);
  if (!existsSync(absolutePath)) {
    return "";
  }
  return readFileSync(absolutePath, "utf8");
}

function looksLikeSourceMaterialPath(value) {
  const text = String(value || "").trim();
  return Boolean(text) && (/[/\\]/.test(text) || /\.(md|txt|json|csv|srt|vtt|html?)$/i.test(text));
}

function sourceMaterialPathReferences(brief) {
  const references = [];
  const addPath = (pathValue) => {
    const value = String(pathValue || "").trim();
    if (!value) return;
    const absolutePath = resolve(ROOT, value);
    references.push({
      path: value,
      absolutePath,
      exists: existsSync(absolutePath),
    });
  };
  if (brief?.sourcePath) addPath(brief.sourcePath);
  const sourceMaterial = brief?.sourceMaterial;
  if (typeof sourceMaterial === "string" && looksLikeSourceMaterialPath(sourceMaterial)) {
    addPath(sourceMaterial);
  } else if (sourceMaterial && typeof sourceMaterial === "object" && sourceMaterial.path) {
    addPath(sourceMaterial.path);
  }
  if (Array.isArray(brief?.sourceMaterials)) {
    for (const item of brief.sourceMaterials) {
      if (typeof item === "string" && looksLikeSourceMaterialPath(item)) addPath(item);
      else if (item && typeof item === "object" && item.path) addPath(item.path);
    }
  }
  return references;
}

function sourceMaterialTextFromBrief(brief) {
  const candidates = [
    brief?.sourceText,
    brief?.fullText,
    brief?.fullContent,
    brief?.chapterText,
    brief?.article,
    brief?.content,
    brief?.transcript,
  ];
  const sourceMaterial = brief?.sourceMaterial;
  if (typeof sourceMaterial === "string") {
    candidates.push(readSourceMaterialPath(sourceMaterial) || sourceMaterial);
  } else if (sourceMaterial && typeof sourceMaterial === "object") {
    candidates.push(
      sourceMaterial.text,
      sourceMaterial.content,
      sourceMaterial.body,
      sourceMaterial.raw,
    );
    if (sourceMaterial.path) {
      candidates.push(readSourceMaterialPath(sourceMaterial.path));
    }
  }
  if (Array.isArray(brief?.sourceMaterials)) {
    for (const item of brief.sourceMaterials) {
      if (typeof item === "string") candidates.push(item);
      else if (item && typeof item === "object") {
        candidates.push(item.text, item.content, item.body, item.raw);
        if (item.path) candidates.push(readSourceMaterialPath(item.path));
      }
    }
  }
  return candidates
    .map((item) => String(item || "").trim())
    .filter(Boolean)
    .sort((a, b) => b.length - a.length)[0] || "";
}

function condensedSourceExplicitlyAllowed(brief, args = {}) {
  if (args["allow-condensed-source"]) return true;
  if (brief?.allowCondensedSourceMaterial === true) return true;
  if (brief?.allowSummarySourceMaterial === true) return true;
  const mode = String(brief?.contentMode || brief?.coverageMode || brief?.sourceMaterialMode || brief?.outputMode || "").toLowerCase();
  return /summary|condensed|digest|short/.test(mode);
}

function buildContentCoverage({ brief, narration, frames, args = {} }) {
  const sourceText = sourceMaterialTextFromBrief(brief);
  const pathReferences = sourceMaterialPathReferences(brief);
  const missingPaths = pathReferences.filter((item) => !item.exists);
  const sourceChars = textCharCount(sourceText);
  const narrationChars = textCharCount(narration);
  const coverageRatio = sourceChars ? Number((narrationChars / sourceChars).toFixed(4)) : null;
  const condensedAllowed = condensedSourceExplicitlyAllowed(brief, args);
  const fullSourcePresent = sourceChars >= 1200;
  const requiredMinimumRatio = fullSourcePresent && !condensedAllowed ? FULL_CONTENT_MIN_COVERAGE_RATIO : null;
  const passes = !missingPaths.length && (!requiredMinimumRatio || coverageRatio >= requiredMinimumRatio);
  return {
    schemaVersion: 1,
    policy: "When full source material is present, final narration must cover the source unless summary/condensed mode is explicitly requested.",
    sourceMaterial: {
      present: Boolean(sourceText),
      kind: brief?.sourceMaterial?.kind || null,
      path: brief?.sourceMaterial?.path || null,
      chars: sourceChars,
      pathReferences,
      missingPaths,
    },
    outputScript: {
      narrationChars,
      sceneCount: Array.isArray(frames) ? frames.length : 0,
      estimatedDurationSeconds: estimateAutoDuration({ narration, frames, brief }),
    },
    coverageRatio,
    condensedAllowed,
    requiredMinimumRatio,
    status: passes ? "pass" : "fail",
    failure: passes
      ? null
      : missingPaths.length
        ? `Source material path not found: ${missingPaths.map((item) => item.path).join(", ")}`
        : "Full source material is much longer than the rendered narration. This run would produce a condensed video instead of a full-content video.",
  };
}

function assertContentCoverage({ out, coverage }) {
  ensureDir(join(out, "workflow"));
  writeJson(join(out, "workflow", "content-coverage.json"), coverage);
  if (coverage.status === "fail") {
    if (coverage.sourceMaterial?.missingPaths?.length) {
      fail(`Full-content coverage failed: ${coverage.failure}. Fix the sourceMaterial path before rendering.`);
    }
    fail(`Full-content coverage failed: source has ${coverage.sourceMaterial.chars} chars but narration has ${coverage.outputScript.narrationChars} chars (${Math.round((coverage.coverageRatio || 0) * 100)}%). Pass --allow-condensed-source only for an explicit summary/digest run.`);
  }
}

function visualFrameLimitFromBrief(brief, args = {}, runtimeDefaults = {}) {
  const requested = Number(firstDefined(args["max-visual-frames"], brief.maxVisualFrames, runtimeDefaults.maxVisualFrames, 0));
  if (Number.isFinite(requested) && requested >= 3) return Math.floor(requested);
  return DEFAULT_MAX_VISUAL_FRAMES;
}

function sceneStyleValue(scene = {}) {
  return scene.visualStyle || scene.styleArchetype || scene.styleTemplate || scene.style || "";
}

function sceneStyleIsLocked(brief = {}, scene = {}) {
  return scene.lockVisualStyle === true
    || scene.visualStyleLocked === true
    || scene.lockStyle === true
    || brief.lockSceneVisualStyles === true
    || brief.respectSceneVisualStyles === true;
}

function repeatedCycle(values, { minItems = 6, minDistinct = 3, maxPattern = 6 } = {}) {
  const normalized = values.map((value) => String(value || "").trim()).filter(Boolean);
  if (normalized.length < minItems) return null;
  for (let patternLength = 2; patternLength <= Math.min(maxPattern, Math.floor(normalized.length / 2)); patternLength += 1) {
    const pattern = normalized.slice(0, patternLength);
    if (new Set(pattern).size < minDistinct) continue;
    let matches = 0;
    for (let index = 0; index < normalized.length; index += 1) {
      if (normalized[index] === pattern[index % patternLength]) matches += 1;
    }
    const matchRatio = matches / normalized.length;
    if (matchRatio >= 0.85) {
      return {
        detected: true,
        pattern,
        patternLength,
        matchRatio: Number(matchRatio.toFixed(3)),
      };
    }
  }
  return null;
}

function styleOverridePolicyForScenes(brief = {}, scenes = []) {
  const unlockedScenes = scenes.filter((scene) => !sceneStyleIsLocked(brief, scene));
  const sceneStyles = unlockedScenes.map((scene) => normalizeStyleKey(sceneStyleValue(scene))).filter(Boolean);
  const scenePalettes = unlockedScenes.map((scene) => palettes[scene.palette] ? scene.palette : "").filter(Boolean);
  const styleCycle = repeatedCycle(sceneStyles);
  const paletteCycle = repeatedCycle(scenePalettes, { minItems: 6, minDistinct: 4, maxPattern: 10 });
  const ignoreSceneStyleOverrides = Boolean(styleCycle);
  const ignoreScenePaletteOverrides = Boolean(paletteCycle);
  return {
    ignoreSceneStyleOverrides,
    ignoreScenePaletteOverrides,
    sceneStyleOverrideMode: ignoreSceneStyleOverrides ? "ignore-mechanical-cycle" : "respect-explicit-unlocked",
    scenePaletteOverrideMode: ignoreScenePaletteOverrides ? "ignore-mechanical-cycle" : "respect-explicit-unlocked",
    mechanicalStyleCycleDetected: Boolean(styleCycle),
    mechanicalPaletteCycleDetected: Boolean(paletteCycle),
    styleCycle,
    paletteCycle,
    lockFields: ["lockVisualStyle", "visualStyleLocked", "lockStyle", "lockSceneVisualStyles", "respectSceneVisualStyles"],
    reason: ignoreSceneStyleOverrides || ignoreScenePaletteOverrides
      ? "Scene visualStyle/palette fields match a repeated template cycle, so the planner treats them as generation residue unless explicitly locked."
      : "No repeated scene style/palette cycle detected; explicit scene overrides remain eligible.",
  };
}

function inferredPaletteForScene({ brief, scene, index, paletteOrder, previousPalette = "" }) {
  const sceneText = [
    brief?.title,
    brief?.objective,
    scene?.id,
    scene?.label,
    ...(Array.isArray(scene?.headline) ? scene.headline : [scene?.headline]),
    scene?.body,
    scene?.subtitle,
    scene?.stat,
  ].filter(Boolean).join("|");
  const selected = paletteOrder[stableIndex(sceneText || `scene-${index + 1}`, paletteOrder.length)] || paletteOrder[index % paletteOrder.length];
  if (selected === previousPalette && paletteOrder.length > 1) {
    const nextIndex = (paletteOrder.indexOf(selected) + 1 + stableIndex(`${sceneText}|palette-adjacent`, paletteOrder.length - 1)) % paletteOrder.length;
    return paletteOrder[nextIndex] || selected;
  }
  return selected;
}

function normalizeFrames(brief, duration, options = {}) {
  const raw = Array.isArray(brief.scenes) && brief.scenes.length >= 3 ? brief.scenes : [];
  const maxFrames = Number(options.maxFrames || DEFAULT_MAX_VISUAL_FRAMES);
  if (raw.length > maxFrames && !options.allowSceneTruncation) {
    fail(`Brief contains ${raw.length} scenes but max visual frames is ${maxFrames}. Refusing to silently truncate scenes; raise --max-visual-frames or set allowSceneTruncation only for an explicit draft.`);
  }
  const paletteOrder = paletteOrderForBrief(brief);
  const styleOverridePolicy = styleOverridePolicyForScenes(brief, raw.slice(0, maxFrames));
  let previousPalette = "";
  const frames = raw.slice(0, maxFrames).map((scene, index) => {
    const rawVisualStyle = sceneStyleValue(scene);
    const visualStyleLocked = sceneStyleIsLocked(brief, scene);
    const ignoreVisualStyle = styleOverridePolicy.ignoreSceneStyleOverrides && !visualStyleLocked;
    const ignorePalette = styleOverridePolicy.ignoreScenePaletteOverrides && !visualStyleLocked;
    const inferredPalette = inferredPaletteForScene({ brief, scene, index, paletteOrder, previousPalette });
    const selectedPalette = palettes[scene.palette] && !ignorePalette ? scene.palette : inferredPalette;
    previousPalette = selectedPalette;
    return {
      id: scene.id || `scene-${index + 1}`,
      label: scene.label || `Scene ${index + 1}`,
      kicker: scene.kicker || `${String(index + 1).padStart(2, "0")} / POINT`,
      headline: Array.isArray(scene.headline) ? scene.headline.slice(0, 3) : [scene.headline || scene.label || `Scene ${index + 1}`],
      stat: scene.stat || String(index + 1),
      body: scene.body || scene.subtitle || "",
      subtitle: scene.subtitle || scene.body || "",
      narration: scene.narration || scene.voiceover || "",
      visualStyle: ignoreVisualStyle ? "" : rawVisualStyle,
      visualStyleHint: ignoreVisualStyle ? rawVisualStyle : "",
      visualStyleLocked,
      visualStyleDecision: ignoreVisualStyle ? "ignored-mechanical-cycle" : rawVisualStyle ? "explicit-scene-style" : "planner-inferred",
      paletteDecision: palettes[scene.palette] && !ignorePalette ? "explicit-scene-palette" : ignorePalette ? "ignored-mechanical-cycle" : "content-inferred",
      chartData: scene.chartData || null,
      formula: scene.formula || "",
      motionTemplate: scene.motionTemplate || "",
      htmlMotionTemplate: scene.htmlMotionTemplate || "",
      templateId: scene.templateId || "",
      visualMode: scene.visualMode || "",
      diagramMode: scene.diagramMode || "",
      pptMode: scene.pptMode || "",
      agentCount: scene.agentCount || null,
      motionLibrary: scene.motionLibrary || "",
      animationLibrary: scene.animationLibrary || "",
      lottieAsset: scene.lottieAsset || "",
      authorizedLottieAsset: scene.authorizedLottieAsset || "",
      productSurface: scene.productSurface || null,
      productFlow: scene.productFlow || null,
      uiFlow: scene.uiFlow || null,
      websiteUrl: scene.websiteUrl || "",
      sourceVideo: scene.sourceVideo || "",
      rawFootage: scene.rawFootage || "",
      clipPath: scene.clipPath || "",
      palette: selectedPalette,
    };
  });
  Object.defineProperty(frames, "styleOverridePolicy", {
    value: styleOverridePolicy,
    enumerable: false,
  });
  if (!frames.length) fail("Brief must contain at least three scenes for this video workflow.");
  const total = Math.max(MIN_DURATION_SECONDS, Number(duration) || DEFAULT_DURATION);
  let cursor = 0;
  const timedFrames = frames.map((frame, index) => {
    const next = index === frames.length - 1
      ? total
      : Number((((index + 1) * total) / frames.length).toFixed(3));
    const durationSec = Number((next - cursor).toFixed(3));
    cursor = next;
    return { ...frame, durationSec };
  });
  Object.defineProperty(timedFrames, "styleOverridePolicy", {
    value: styleOverridePolicy,
    enumerable: false,
  });
  return timedFrames;
}

function textComparable(value) {
  return String(value || "").replace(/\s+/g, "");
}

function frameNarrationSegments(narration, frames) {
  const expected = textComparable(narration);
  const explicit = frames.map((frame, index) => ({
    index: index + 1,
    frameId: frame.id,
    label: frame.label,
    text: String(frame.narration || frame.spokenText || frame.subtitle || "").trim(),
  }));
  const explicitText = explicit.map((segment) => segment.text).join("");
  if (explicit.every((segment) => segment.text) && textComparable(explicitText) === expected) {
    return explicit;
  }

  const sentences = splitSentences(narration);
  if (!sentences.length) {
    throw new Error("Cannot build frame-bound narration segments: narration has no sentence boundaries.");
  }
  if (sentences.length < frames.length) {
    throw new Error(`Cannot bind audio to ${frames.length} visual frames from only ${sentences.length} spoken sentences. Add per-scene narration fields or reduce scenes.`);
  }

  const counts = Array.from({ length: frames.length }, () => Math.floor(sentences.length / frames.length));
  let remainder = sentences.length - counts.reduce((sum, count) => sum + count, 0);
  if (remainder > 0 && counts.length) {
    counts[0] += 1;
    remainder -= 1;
  }
  if (remainder > 0 && counts.length > 1) {
    counts[counts.length - 1] += 1;
    remainder -= 1;
  }
  for (let i = 1; remainder > 0 && i < counts.length - 1; i += 1) {
    counts[i] += 1;
    remainder -= 1;
  }

  let cursor = 0;
  const segments = frames.map((frame, index) => {
    const count = index === frames.length - 1
      ? sentences.length - cursor
      : Math.max(1, counts[index] || 0);
    const text = joinCaptionTextParts(sentences.slice(cursor, cursor + count));
    cursor += count;
    return {
      index: index + 1,
      frameId: frame.id,
      label: frame.label,
      text,
    };
  });
  const actual = textComparable(segments.map((segment) => segment.text).join(""));
  if (actual !== expected) {
    throw new Error("Frame narration segmentation did not preserve spoken narration exactly.");
  }
  return segments;
}

function joinCaptionTextParts(parts) {
  const cleaned = parts.map((part) => String(part || "").trim()).filter(Boolean);
  if (!cleaned.length) return "";
  if (!cleaned.some((part) => /[A-Za-z0-9]/u.test(part))) return cleaned.join("");
  return cleaned.join(" ").replace(/\s+([,.;:!?])/g, "$1").replace(/\s+/g, " ").trim();
}

function splitSemanticCueTexts(text, maxChars = 120) {
  const sentences = splitSentences(text);
  const parts = sentences.length ? sentences : [String(text || "").trim()].filter(Boolean);
  const cues = [];
  let current = "";
  const flushCurrent = () => {
    if (current) {
      cues.push(current);
      current = "";
    }
  };
  for (const sentence of parts) {
    if (sentence.length <= maxChars) {
      if (current && current.length + sentence.length > maxChars) {
        flushCurrent();
      }
      current = current ? joinCaptionTextParts([current, sentence]) : sentence;
      continue;
    }
    flushCurrent();
    const semanticParts = sentence
      .match(/[^：:；;]+[：:；;]?/gu)
      ?.map((part) => part.trim())
      .filter(Boolean) || [];
    if (!semanticParts.length || semanticParts.some((part) => part.length > maxChars)) {
      cues.push(sentence);
      continue;
    }
    let semanticCurrent = "";
    for (const part of semanticParts) {
      if (semanticCurrent && semanticCurrent.length + part.length > maxChars) {
        cues.push(semanticCurrent);
        semanticCurrent = part;
      } else {
        semanticCurrent = semanticCurrent ? joinCaptionTextParts([semanticCurrent, part]) : part;
      }
    }
    if (semanticCurrent) cues.push(semanticCurrent);
  }
  flushCurrent();
  return cues;
}

function subtitleCueNarrationSegments(frameSegments) {
  const cueSegments = [];
  for (const frameSegment of frameSegments) {
    const cueTexts = splitSemanticCueTexts(frameSegment.text);
    if (!cueTexts.length) {
      throw new Error(`Cannot build subtitle cue segments for ${frameSegment.frameId}: no cue text.`);
    }
    const rebuilt = cueTexts.join("");
    if (textComparable(rebuilt) !== textComparable(frameSegment.text)) {
      throw new Error(`Subtitle cue segmentation did not preserve frame text for ${frameSegment.frameId}`);
    }
    cueTexts.forEach((text, cueIndex) => {
      cueSegments.push({
        index: cueSegments.length + 1,
        frameId: frameSegment.frameId,
        label: `${frameSegment.label} · cue ${cueIndex + 1}`,
        text,
        captionText: splitCaptionLines(text, 24).join("\n"),
        cueIndex: cueIndex + 1,
        cueCount: cueTexts.length,
        parentFrameSegmentIndex: frameSegment.index,
        frameText: frameSegment.text,
      });
    });
  }
  const frameText = frameSegments.map((segment) => segment.text).join("");
  const cueText = cueSegments.map((segment) => segment.text).join("");
  if (textComparable(frameText) !== textComparable(cueText)) {
    throw new Error("Cue-level narration segmentation did not preserve spoken narration exactly.");
  }
  return cueSegments;
}

function applyAudioTimingsToFrames(frames, segmentTimings) {
  if (!Array.isArray(segmentTimings) || !segmentTimings.length) {
    throw new Error("Missing audio segment timings.");
  }
  const byFrame = new Map();
  for (const timing of segmentTimings) {
    const list = byFrame.get(timing.frameId) || [];
    list.push(timing);
    byFrame.set(timing.frameId, list);
  }
  return frames.map((frame, index) => {
    const timings = (byFrame.get(frame.id) || []).sort((a, b) => Number(a.index || 0) - Number(b.index || 0));
    if (!timings.length) {
      throw new Error(`Frame/audio segment missing at ${index + 1}: ${frame.id}`);
    }
    const spokenText = timings.map((timing) => timing.text || "").join("");
    const durationSec = Number(timings.reduce((sum, timing) => sum + Number(timing.durationSeconds || 0), 0).toFixed(3));
    if (!durationSec || durationSec < 0.1) {
      throw new Error(`Invalid TTS segment duration for ${frame.id}: ${durationSec}`);
    }
    if (textComparable(spokenText) !== textComparable(timings[0]?.frameText || spokenText)) {
      throw new Error(`Cue-level TTS text did not preserve frame narration for ${frame.id}`);
    }
    const frameStart = Number(timings[0].start || 0);
    const subtitleCues = timings.map((timing, cueIndex) => ({
      index: cueIndex + 1,
      sourceSegmentIndex: timing.index,
      text: timing.captionText || timing.text || "",
      spokenText: timing.text || "",
      start: Number((Number(timing.start || 0) - frameStart).toFixed(3)),
      end: Number((Number(timing.end || 0) - frameStart).toFixed(3)),
      duration: Number(timing.durationSeconds || 0),
      absoluteAudioStart: Number(timing.start || 0),
      absoluteAudioEnd: Number(timing.end || 0),
      files: timing.files || [],
    }));
    return {
      ...frame,
      durationSec,
      subtitle: frame.subtitle,
      displaySubtitle: conciseCaptionText(frame),
      spokenText,
      subtitleCues,
      audioSegment: {
        index: timings[0].index,
        start: Number(timings[0].start || 0),
        end: Number(timings[timings.length - 1].end || 0),
        durationSeconds: durationSec,
        segmentCount: timings.length,
        source: timings.some((timing) => timing.source === "provided_audio_estimated")
          ? "provided_audio_estimated"
          : "local_tts",
      },
    };
  });
}

function aspectRatio(width, height) {
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const divisor = gcd(width, height);
  return `${width / divisor}:${height / divisor}`;
}

