function coverTitleDescription(value) {
  return String(value || "")
    .replace(/^第\s*[\d０-９一二三四五六七八九十百]+\s*[章节讲集课期]*\s*[：:、.\-\s]+/u, "")
    .trim();
}

function coverHookFromTitle(value, language = "zh") {
  const title = coverTitleDescription(value) || String(value || "").trim();
  if (!title) return "";
  if (language === "en") return title.replace(/\s+/g, " ").trim();
  const normalized = title.replace(/\s+/g, " ").trim();
  if (/logline/i.test(normalized) && /、/.test(normalized) && /与/.test(normalized)) {
    return normalized.replace(/、\s*Logline\s*与\s*/i, "\nLogline 与 ");
  }
  if (normalized.length > 12) {
    const splitAt = normalized.search(/[：:、；;]/u);
    if (splitAt > 2 && splitAt < normalized.length - 2) {
      return `${normalized.slice(0, splitAt)}\n${normalized.slice(splitAt + 1)}`;
    }
  }
  return normalized;
}

function deriveCoverTexts({ coverPromise, coverTitle, frames, language = "zh" }) {
  const compact = (value, max) => String(value || "")
    .replace(/[：:，,。！？!?；;]/g, " ")
    .replace(/\s+/g, language === "en" ? " " : "")
    .trim()
    .slice(0, max);
  const topicPayoff = (raw) => {
    const text = String(raw || "");
    if (/静音|开头|前三秒|3\s*秒|流失|划走|留住/.test(text)) return "别静音开场";
    if (/PPT/i.test(text)) return "摆脱PPT感";
    if (/设计|审美/.test(text)) return "审美变成规则";
    if (/动效|动画|交互/.test(text)) return "让画面会思考";
    if (/视频/.test(text)) return "像视频不是PPT";
    if (/小说|读者|章节|写作/.test(text)) return "承诺才留人";
    return "看完能行动";
  };
  const writingMethodHook = (raw) => {
    const text = String(raw || "");
    const rules = [
      [/小说不是灵感产品|不是灵感|灵感产品|灵感/, ["灵感不够", "读者买承诺", "别等灵感"]],
      [/题材|平台|读者画像|读者/, ["写给谁看?", "题材先匹配", "别选错战场"]],
      [/一句话卖点|卖点|核心循环|循环/, ["一句话卖点", "追更靠循环", "先卖清楚"]],
      [/故事发动机|发动机/, ["故事会自转", "欲望冲突供能", "别靠硬推"]],
      [/冲突三层|三层冲突|冲突/, ["冲突不止吵", "三层一起压", "压力从哪来"]],
      [/筹码|压迫/, ["筹码上桌", "压迫逼选择", "代价够不够"]],
      [/钩子系统|钩子/, ["钩子别断", "每段给追问", "一直想看"]],
      [/爽点|压缩释放|释放/, ["爽点要蓄压", "压住再释放", "爆点才爽"]],
      [/黄金开篇|开篇|开头|第一章/, ["开头没人看?", "第一章留人", "为什么翻走"]],
      [/长篇规划|规划|大纲|长篇/, ["写着写着崩?", "先搭骨架", "后面不塌"]],
      [/雪花法|递进规划|递进/, ["一句话变全书", "从小到大", "别一上来硬写"]],
      [/场景|最小故事单元/, ["每场都要变", "别写流水账", "一场一推动"]],
      [/章纲|Scene Contract|场景契约/, ["章纲别空写", "每章有合同", "写前先锁定"]],
      [/伏笔|契诃夫|Payoff Ledger|回收/, ["埋了就兑现", "伏笔别失踪", "回收才爽"]],
      [/反转|误导/, ["反转别硬拧", "骗读者要公平", "真正原因"]],
      [/角色三支柱|角色支柱/, ["角色立不住?", "三根柱子", "别只写人设"]],
      [/角色弧线|关系债/, ["关系债推进", "人物会变", "别原地打转"]],
      [/反派|对手/, ["对手越强越稳", "反派别工具化", "压力才好看"]],
      [/对话声纹|声纹|对白|对话/, ["一听就知道谁", "对白别同腔", "声音有身份"]],
      [/画面感|文采/, ["先让人看见", "文采别堆词", "画面压过形容"]],
      [/去\s*AI\s*味|AI味|AI 味/, ["别像模板文", "去掉AI腔", "让句子像人写"]],
      [/节奏|信息编排/, ["信息给太早?", "节奏会控场", "别一次说完"]],
      [/审稿|修稿|闭环/, ["修完再复检", "审稿有闭环", "别只改错字"]],
      [/脑洞|连载样稿|样稿/, ["脑洞变样稿", "先写可连载", "别停在设定"]],
    ];
    const match = rules.find(([pattern]) => pattern.test(text));
    if (!match) return null;
    const [hookText, payoffText, gapText] = match[1];
    return {
      hookText,
      payoffText,
      curiosityGap: `为什么「${coverTitleDescription(text).replace(/^写小说方法论[：:]?/u, "") || text}」决定读者会不会继续看？`,
      viewerDecision: `一秒内看懂：这不是课程PPT，而是解决「${hookText.replace("?", "")}」的写作封面承诺。`,
    };
  };
  const workflowHook = (raw) => {
    const text = String(raw || "");
    if (!/codex\s*video\s*workflow|视频生成工作流|视频生成\s*skill|视频自动生成|全链路.*(?:视频|封面|QC)|(?:封面|字幕|动效|页面).*(?:合成|QC|质量门禁)/i.test(text)) return null;
    return {
      hookText: "别交半成品",
      payoffText: "全链路可验证",
      curiosityGap: "为什么生成视频不能只看导出 MP4，而要同时看封面、页面、字幕、动效、语音和 QC 证据？",
      viewerDecision: "一秒内看懂：这不是配置页截图，而是一套能把脚本、封面、视频页面和质量证据打通的视频生成工作流。",
    };
  };
  const genericCuriosityGap = (raw) => {
    const text = String(raw || "");
    if (/静音|开头|前三秒|3\s*秒|流失|划走|留住/.test(text)) return "为什么前三秒没声音，会让用户误以为视频坏了？";
    if (/PPT/i.test(text)) return "为什么同样是AI生成，有些像体验，有些像PPT？";
    if (/设计|审美/.test(text)) return "为什么参考网站不能只当素材库，而要变成生成规则？";
    if (/动效|动画|交互/.test(text)) return "画面到底为什么动，观众才会继续看？";
    if (/小说|读者|章节|写作/.test(text)) return "为什么宏大设定留不住人，而普通文笔能让读者追下去？";
    return "这个方法如何把抽象需求变成可验证的成片？";
  };
  const genericViewerDecision = (raw) => {
    const text = String(raw || "");
    if (/静音|开头|前三秒|3\s*秒|流失|划走|留住/.test(text)) return "一秒内看懂：封面继续兑现点击承诺，口播必须立刻开始。";
    if (/PPT/i.test(text)) return "一秒内看懂：不是多加动画，而是先规划视觉任务、动效动词、交互感和叙事合同。";
    if (/设计|审美/.test(text)) return "一秒内看懂：审美不是装饰，而是可复用、可检查的生成规则。";
    if (/小说|读者|章节|写作/.test(text)) return "一秒内看懂：问题不在灵感，而在能不能持续兑现读者情绪。";
    return "一秒内看懂：这支视频有明确承诺、路径和验证证据。";
  };
  const rawTitle = coverTitleDescription(coverTitle);
  const raw = String(rawTitle || coverPromise || (language === "en" ? "Proof, not just render" : "核心承诺"));
  if (language !== "en") {
    const workflow = workflowHook(raw);
    if (workflow) return workflow;
    const methodHook = writingMethodHook(raw);
    if (methodHook) return methodHook;
  }
  if (language === "en") {
    const payoffSource = frames.find((frame) => frame.headline?.some((item) => item !== coverPromise))?.headline?.[1]
      || frames[1]?.headline?.[0]
      || "Evidence package";
    return {
      hookText: compact(coverHookFromTitle(raw, language), 36) || "Proof, not just render",
      payoffText: compact(payoffSource, 24) || "Evidence package",
      curiosityGap: "What changes when a video workflow proves the script, timing, visuals, voice, cover, and QC instead of only exporting an MP4?",
      viewerDecision: "Understand in one second: this skill turns a brief into a reviewed, reproducible video package.",
    };
  }
  const hookText = coverHookFromTitle(raw, language) || compact(raw, 18);
  const headlinePool = frames
    .flatMap((frame) => frame.headline || [])
    .map((item) => String(item || "").trim())
    .filter((item) => item && item !== coverPromise && item !== raw && !/^(封面承诺|核心承诺|视频封面)$/u.test(item));
  const topicalPayoff = topicPayoff(raw);
  const payoffSource = headlinePool.find((item) => /静音|开头|秒|流失|留住|PPT|视频|审美|设计|规则|动效|动画|交互|流程|质感|承诺|读者/.test(item) && item.length <= 12)
    || topicalPayoff;
  const payoffText = compact(payoffSource, 9) || topicalPayoff;
  return {
    hookText: hookText || compact(raw, 18) || "核心承诺",
    payoffText,
    curiosityGap: genericCuriosityGap(raw),
    viewerDecision: genericViewerDecision(raw),
  };
}

