function normalizeStyleKey(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/_/g, "-");
}

function inferStyleArchetype(brief, frames, videoType) {
  const explicit = normalizeStyleKey(brief.visualStyle || brief.styleArchetype || brief.styleTemplate || brief.style);
  const aliases = {
    infographic: "animated-infographic",
    "motion-graphics": "animated-infographic",
    motion: "animated-infographic",
    whiteboard: "whiteboard-lesson",
    board: "whiteboard-lesson",
    classroom: "classroom-board",
    school: "classroom-board",
    data: "data-newsroom",
    newsroom: "data-newsroom",
    finance: "data-newsroom",
    screencast: "screen-demo",
    "screen-demo": "screen-demo",
    demo: "screen-demo",
    tutorial: "screen-demo",
    kinetic: "kinetic-typography",
    typography: "kinetic-typography",
    "talking-head": "hybrid-presenter",
    presenter: "hybrid-presenter",
    documentary: "documentary-editorial",
    "video-essay": "documentary-editorial",
    story: "narrative-story-lab",
    writing: "narrative-story-lab",
  };
  if (STYLE_ARCHETYPES[explicit]) return STYLE_ARCHETYPES[explicit];
  if (aliases[explicit] && STYLE_ARCHETYPES[aliases[explicit]]) return STYLE_ARCHETYPES[aliases[explicit]];

  const text = `${brief.title || ""} ${brief.objective || ""} ${brief.audience || ""} ${frames.map((frame) => `${frame.label} ${frame.body} ${frame.subtitle} ${frame.headline.join(" ")}`).join(" ")}`;
  if (videoType === "writing-method" || /小说|网文|写作|故事|剧情|主角|story|novel|writing/i.test(text)) return STYLE_ARCHETYPES["narrative-story-lab"];
  if (videoType === "school-education" || /学校|校园|学生|老师|教师|课堂|课程|教材|school|classroom|teacher|student/i.test(text)) return STYLE_ARCHETYPES["classroom-board"];
  if (/白板|板书|公式|推导|数学|物理|化学|例题|whiteboard|formula|math|physics/i.test(text)) return STYLE_ARCHETYPES["whiteboard-lesson"];
  if (/数据|图表|增长|趋势|财经|金融|市场|政策|统计|chart|data|market|finance|trend/i.test(text)) return STYLE_ARCHETYPES["data-newsroom"];
  if (/教程|步骤|屏幕|软件|工具|工作流|操作|产品演示|素材引擎|检索|下载|入账|归一化|B-roll|screencast|workflow|how to|demo|software|product/i.test(text)) return STYLE_ARCHETYPES["screen-demo"];
  if (darkStageExplicitlyAllowed(brief) && (hasStrongKineticIntent(text) || (/talking head|口播/i.test(text) && briefPrefersKineticHook(brief)))) return STYLE_ARCHETYPES["kinetic-typography"];
  if (/历史|人物|纪实|纪录片|社会|深度|documentary|history|essay/i.test(text)) return STYLE_ARCHETYPES["documentary-editorial"];
  return STYLE_ARCHETYPES["animated-infographic"];
}

function briefPrefersKineticHook(brief = {}, fallback = {}) {
  const explicit = normalizeStyleKey(brief.visualStyle || brief.styleArchetype || brief.styleTemplate || brief.style);
  if (explicit === "kinetic-typography" || explicit === "kinetic" || explicit === "typography") return true;
  if (fallback?.id === "kinetic-typography") return true;
  const text = `${brief.title || ""} ${brief.objective || ""} ${brief.audience || ""} ${brief.platform || ""} ${brief.aspectRatio || ""}`;
  return /抖音|短视频|竖屏|前三秒|3\s*秒|划走|tiktok|tik\s*tok|shorts|reels|short-form|vertical|talking head|quote-driven/i.test(text);
}

function inferSceneStyleArchetype({ brief, frame, index, total, videoType, fallback, allowExplicitSceneStyle = true }) {
  const explicit = normalizeStyleKey(frame.visualStyle || frame.styleArchetype || frame.styleTemplate || frame.style);
  const aliases = {
    infographic: "animated-infographic",
    "motion-graphics": "animated-infographic",
    whiteboard: "whiteboard-lesson",
    classroom: "classroom-board",
    data: "data-newsroom",
    newsroom: "data-newsroom",
    screencast: "screen-demo",
    demo: "screen-demo",
    tutorial: "screen-demo",
    kinetic: "kinetic-typography",
    typography: "kinetic-typography",
    presenter: "hybrid-presenter",
    documentary: "documentary-editorial",
    story: "narrative-story-lab",
  };
  if (allowExplicitSceneStyle) {
    const explicitKinetic = explicit === "kinetic-typography" || aliases[explicit] === "kinetic-typography";
    const kineticAllowed = frame.visualStyleLocked === true
      || frame.lockVisualStyle === true
      || frame.lockStyle === true
      || darkStageExplicitlyAllowed(brief, frame);
    if (explicitKinetic && !kineticAllowed) {
      return videoType === "writing-method"
        ? STYLE_ARCHETYPES["narrative-story-lab"]
        : STYLE_ARCHETYPES["animated-infographic"];
    }
    if (STYLE_ARCHETYPES[explicit]) return STYLE_ARCHETYPES[explicit];
    if (aliases[explicit] && STYLE_ARCHETYPES[aliases[explicit]]) return STYLE_ARCHETYPES[aliases[explicit]];
  }

  const sceneText = `${frame.label || ""} ${frame.subtitle || ""} ${frame.body || ""} ${(frame.headline || []).join(" ")}`;
  const briefText = `${brief.title || ""} ${brief.objective || ""}`;
  const text = `${sceneText} ${index === 0 ? briefText : ""}`;
  if (videoType === "writing-method") {
    if (index === 0 && darkStageExplicitlyAllowed(brief, frame) && briefPrefersKineticHook(brief, fallback) && /前三秒|3\s*秒|钩子|开头|留住|划走|短视频/.test(text)) return STYLE_ARCHETYPES["kinetic-typography"];
    if (/数据|表格|清单|检查|对照|声纹|问题/.test(sceneText)) return STYLE_ARCHETYPES["animated-infographic"];
    return STYLE_ARCHETYPES["narrative-story-lab"];
  }
  if (index === 0 && darkStageExplicitlyAllowed(brief, frame) && briefPrefersKineticHook(brief, fallback) && /前三秒|3\s*秒|钩子|开头|留住|划走|短视频/.test(text)) return STYLE_ARCHETYPES["kinetic-typography"];
  if (/视觉|动起来|动画|动效|信息|PPT|堆文字|解决方案|变化/.test(sceneText)) return STYLE_ARCHETYPES["animated-infographic"];
  if (/封面|口播|进场|工作流|操作|工具|流程|步骤|播放|声音/.test(sceneText)) return STYLE_ARCHETYPES["screen-demo"];
  if (/静音|流失|曲线|趋势|下降|增长|数据|判断区|误会|坏了|划走/.test(sceneText)) return STYLE_ARCHETYPES["data-newsroom"];
  if (index === total - 1 && fallback?.id === "kinetic-typography") return STYLE_ARCHETYPES["animated-infographic"];
  if (videoType === "school-education") return STYLE_ARCHETYPES["classroom-board"];
  return fallback || STYLE_ARCHETYPES["animated-infographic"];
}

function inferVideoType(brief, frames) {
  const explicit = String(brief.videoType || brief.type || "").trim();
  if (DESIGN_TEMPLATES[explicit]) return explicit;
  if (/^(school|education|course|lesson|classroom)$/i.test(explicit)) return "school-education";
  const text = `${brief.title || ""} ${brief.objective || ""} ${brief.audience || ""} ${frames.map((frame) => `${frame.label} ${frame.body} ${frame.headline.join(" ")}`).join(" ")}`;
  if (/小说|网文|写作|章节|悬念|反转|文笔|剧情|主角/.test(text)) return "writing-method";
  if (/学校|校园|学生|老师|教师|课堂|课程|教材|学习|教育|school|education|classroom|teacher|student|lesson|course/i.test(text)) return "school-education";
  if (/数据|图表|增长|趋势|财经|金融|市场|政策|统计|chart|data|market|finance|trend/i.test(text)) return "professional-explainer";
  if (/教程|步骤|怎么|方法|workflow|how to/i.test(text)) return "tutorial-explainer";
  return "professional-explainer";
}

function visualRoleForFrame(type, frame, index, total) {
  if (type === "writing-method") {
    const coreText = `${frame.id || ""} ${frame.label || ""} ${frame.body || ""} ${frame.subtitle || ""} ${(frame.headline || []).join("")}`;
    const fullText = `${coreText} ${frame.narration || ""} ${frame.spokenText || ""}`;
    const hasCore = (pattern) => pattern.test(coreText);
    const hasAny = (pattern) => pattern.test(fullText);
    if (index === 0) return "hook";
    if (hasCore(/六个问题|反推|检查|清单|自检/)) return "diagnostic-check";
    if (hasCore(/structural|cause|结构|原因|症状|根因|底层|机制/)) return "causal-structure";
    if (hasCore(/潜台词|暗线|隐藏|水下|没说出口|不能说出口/)) return "subtext-layers";
    if (hasCore(/真实目的|真实目标|表层|表面|目的|想要|真正|目标|动机/)) return "surface-intent";
    if (hasCore(/author|mouthpiece|作者|借嘴|传声筒|代言|旁白|说教|角色.*说|替.*说/)) return "voice-mediation";
    if (hasCore(/站起来|选择|行动|承担/)) return "character-standup";
    if (hasCore(/状态|变化|改变|关系|风险|代价|去哪儿|权力/)) return "state-shift";
    if (hasCore(/声纹|语气|口吻|谁在说|语言习惯|常用词|禁用词|句长/)) return "voiceprint-map";
    if (hasCore(/对白|台词|废话|明白|说出来|说清楚|分不清/)) return "dialogue-autopsy";
    if (hasCore(/开头|第一秒|葬礼/)) return "opening-anomaly";
    if (hasCore(/冲突|欲望|阻碍|倒计时/)) return "conflict-system";
    if (hasCore(/章节|悬念/)) return "chapter-question";
    if (hasCore(/反转|重写|新信息/)) return "twist-rewrite";
    if (hasCore(/删|三刀|编辑/)) return "edit-pass";
    if (hasAny(/六个问题|反推|检查|清单|自检/)) return "diagnostic-check";
    if (hasAny(/structural|cause|结构|原因|症状|根因|底层|机制/)) return "causal-structure";
    if (hasAny(/潜台词|暗线|隐藏|水下|没说出口|不能说出口/)) return "subtext-layers";
    if (hasAny(/真实目的|真实目标|表层|表面|目的|想要|真正|目标|动机/)) return "surface-intent";
    if (hasAny(/author|mouthpiece|作者|借嘴|传声筒|代言|旁白|说教|角色.*说|替.*说/)) return "voice-mediation";
    if (hasAny(/站起来|选择|行动|承担/)) return "character-standup";
    if (hasAny(/状态|变化|改变|关系|风险|代价|去哪儿|权力/)) return "state-shift";
    if (hasAny(/声纹|语气|口吻|谁在说|语言习惯|常用词|禁用词|句长/)) return "voiceprint-map";
    if (hasAny(/对白|台词|废话|明白|说出来|说清楚|分不清/)) return "dialogue-autopsy";
    if (hasAny(/开头|第一秒|葬礼/)) return "opening-anomaly";
    if (hasAny(/冲突|欲望|阻碍|倒计时/)) return "conflict-system";
    if (hasAny(/章节|悬念/)) return "chapter-question";
    if (hasAny(/反转|重写|新信息/)) return "twist-rewrite";
    if (hasAny(/删|三刀|编辑/)) return "edit-pass";
    return [
      "dialogue-autopsy",
      "subtext-layers",
      "state-shift",
      "voiceprint-map",
      "surface-intent",
      "causal-structure",
    ][Math.max(0, index - 1) % 6];
  }
  if (type === "school-education") {
    if (index === 0) return "lesson-question";
    if (/概念|定义|是什么|原理/.test(`${frame.label} ${frame.headline.join("")}`)) return "concept-note";
    if (/例题|案例|练习|步骤|解法/.test(`${frame.label} ${frame.headline.join("")}`)) return "worked-example";
    if (/测验|检查|巩固|记住|复习/.test(`${frame.label} ${frame.headline.join("")}`)) return "quiz-checkpoint";
    if (index === total - 1) return "memory-map";
    return "guided-note";
  }
  if (index === 0) return "hook";
  if (index === total - 1) return "summary";
  return "method-step";
}

function visualKeywordCandidates(value) {
  const text = String(value || "")
    .replace(/[“”"';；:：,.，。!?！？、()\[\]【】<>《》]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!text) return [];
  const cjk = text.match(/[一-龥A-Za-z0-9]{2,12}/gu) || [];
  const stopWords = new Set([
    "这个", "那个", "我们", "你们", "他们", "一个", "一种", "以及", "然后", "因为", "所以", "如果", "不是", "而是", "可以", "需要", "进行", "当前", "生成", "视频", "画面", "场景", "内容", "信息", "用户",
    "Generate", "professional", "short", "illustration", "style", "scene", "role", "asset", "clear", "layers",
  ]);
  return cjk
    .map((item) => item.trim())
    .filter((item) => item.length >= 2 && !stopWords.has(item));
}

function extractVisualKeywords(page, brief) {
  const frame = page?.frame || {};
  const values = [
    brief?.title,
    brief?.coverTheme,
    frame.label,
    ...(frame.headline || []),
    frame.body,
    frame.subtitle,
    frame.spokenText,
    frame.narration,
    page?.visualRole,
    page?.imageRole,
    page?.shotTemplate,
    page?.styleLabel,
  ];
  const counts = new Map();
  for (const token of values.flatMap(visualKeywordCandidates)) {
    counts.set(token, (counts.get(token) || 0) + 1);
  }
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || b[0].length - a[0].length)
    .map(([token]) => token)
    .slice(0, 12);
}

function promptKeywordCoverage(prompt, keywords) {
  const normalized = String(prompt || "").toLowerCase();
  const required = (keywords || []).filter(Boolean);
  const matched = required.filter((keyword) => normalized.includes(String(keyword).toLowerCase()));
  return {
    required,
    matched,
    missing: required.filter((keyword) => !matched.includes(keyword)),
    ratio: required.length ? Number((matched.length / required.length).toFixed(3)) : 0,
  };
}

