function chartDataPages(designPlan) {
  return (Array.isArray(designPlan.pages) ? designPlan.pages : [])
    .filter((page) => page?.frame?.chartData && typeof page.frame.chartData === "object");
}

function buildDataDrivenMotionArtifacts({ brief, designPlan, motionSelection }) {
  const pages = chartDataPages(designPlan);
  const mathPages = mathMotionPages(designPlan).filter((page) => !pages.some((chartPage) => chartPage.id === page.id));
  const measuredPages = pages.filter((page) => Array.isArray(page.frame.chartData.values) || Array.isArray(page.frame.chartData.nodes));
  const sources = pages.map((page) => {
    const chart = page.frame.chartData;
    return {
      sceneId: page.id,
      chartType: chart.type || "semantic-data-scene",
      sourceName: chart.sourceName || "not supplied",
      sourceUrl: chart.sourceUrl || null,
      sourcePath: chart.sourcePath || null,
      retrievalMethod: chart.sourceUrl ? "brief-provided-public-source-url" : chart.sourcePath ? "brief-provided-local-source-path" : "planner-source-required-before-final-render",
      metricLabel: chart.metricLabel || chart.title || "metric not supplied",
      unit: chart.unit || null,
      period: chart.year || chart.period || null,
      transformation: chart.transformation || "as-provided in brief chartData",
      evidenceStatus: chart.sourceUrl || chart.sourcePath ? "source-declared" : "source-missing",
    };
  });
  const series = pages.map((page) => {
    const chart = page.frame.chartData;
    const points = Array.isArray(chart.values)
      ? chart.values.map((point, index) => ({
        order: index + 1,
        label: String(point.label ?? index + 1),
        value: Number.isFinite(Number(point.value)) ? Number(point.value) : point.value,
        note: point.note || null,
        highlight: point.highlight === true,
      }))
      : [];
    const nodes = Array.isArray(chart.nodes)
      ? chart.nodes.map((node, index) => ({
        order: index + 1,
        label: String(node.label ?? index + 1),
        value: node.value ?? null,
        note: node.note || null,
        highlight: node.highlight === true,
      }))
      : [];
    return {
      sceneId: page.id,
      order: page.sceneIndex,
      title: chart.title || page.frame?.label || page.id,
      chartType: chart.type || "semantic-data-scene",
      metricLabel: chart.metricLabel || null,
      unit: chart.unit || null,
      period: chart.year || chart.period || null,
      points,
      nodes,
      sourceName: chart.sourceName || null,
      sourceUrl: chart.sourceUrl || null,
      evidenceStatus: points.length || nodes.length ? "measured-values-provided" : "qualitative-no-measured-values",
    };
  });
  const qualitativeOnly = (motionSelection?.dataDrivenMotion || mathPages.length > 0) && pages.length === 0;
  return {
    dataSourcePlan: {
      schemaVersion: 1,
      stage: "pre-render-data-source-plan",
      sourceReference: "references/data-driven-motion.md",
      status: qualitativeOnly
        ? mathPages.length
          ? "formula-or-geometry-motion-plan"
          : "qualitative-data-motion-requested"
        : measuredPages.length
          ? "measured-data-provided"
          : "source-required-before-final-render",
      retrievalPolicy: [
        "Use brief-provided chartData when values and source metadata are already present.",
        "Use web/API search only when current measured values are required and not supplied.",
        "If reliable values are unavailable, mark the scene qualitative and do not draw fake precise values.",
        "For formula, proof, physics, or geometry scenes, record the symbolic relationship and renderer route even when no numeric series exists.",
      ],
      videoTitle: brief.title || "",
      selectedTemplate: motionSelection?.selectedTemplate || null,
      scenesNeedingData: pages.map((page) => page.id),
      scenesNeedingMathMotion: mathPages.map((page) => page.id),
      sources,
    },
    dataSeries: {
      schemaVersion: 1,
      stage: "pre-render-data-series",
      status: series.some((item) => item.points.length || item.nodes.length)
        ? "ready"
        : mathPages.length
          ? "formula-or-geometry-only"
          : qualitativeOnly
            ? "qualitative-data-motion-requested"
            : "qualitative-only",
      videoTitle: brief.title || "",
      series,
      formulaScenes: mathPages.map((page) => ({
        sceneId: page.id,
        order: page.sceneIndex,
        title: page.frame?.label || page.id,
        relationship: page.frame?.formula || page.frame?.body || page.frame?.subtitle || "",
        rendererHint: "manim-insert or deterministic SVG proof board",
        evidenceStatus: "symbolic-motion-plan",
      })),
    },
    dataMotionPlan: {
      schemaVersion: 1,
      stage: "pre-render-data-motion-plan",
      sourceReference: "references/data-driven-motion.md",
      selectedTemplate: motionSelection?.selectedTemplate || null,
      rendererRouting: motionSelection?.dataDrivenMotion?.routingRule || "Use data-curve-trace for simple sourced series; escalate to D3/Manim only when chart complexity or formula geometry requires it.",
      evidenceRule: motionSelection?.dataDrivenMotion?.evidenceRule || "Data scenes must show source, metric definition, units, and timing-bound visual evidence.",
      scenes: [
        ...series.map((item) => ({
          sceneId: item.sceneId,
          order: item.order,
          chartType: item.chartType,
          motionVerb: item.chartType === "trend-line" ? "trace" : item.chartType === "ranked-bars" ? "compare" : "reveal",
          timingBinding: "workflow/sync-timecode-plan.json scene segment",
          sourceFootnote: [item.sourceName, item.period].filter(Boolean).join(" · ") || "source required before final render",
          valueCount: item.points.length + item.nodes.length,
          evidenceStatus: item.evidenceStatus,
        })),
        ...mathPages.map((page) => ({
          sceneId: page.id,
          order: page.sceneIndex,
          chartType: "formula-or-geometry-motion",
          motionVerb: "derive",
          timingBinding: "workflow/sync-timecode-plan.json scene segment",
          sourceFootnote: "symbolic relationship from scene narration; no fake measured values",
          valueCount: 0,
          evidenceStatus: "symbolic-motion-plan",
        })),
      ],
      rejectList: [
        "fake precise values",
        "chart without metric definition or unit",
        "curve unrelated to narrated claim",
        "caption collision with axes, endpoint labels, callouts, or source footnote",
      ],
    },
  };
}

function mediaPathsFromValue(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.flatMap(mediaPathsFromValue);
  if (typeof value === "string") return [value];
  if (typeof value === "object") {
    return [value.path, value.file, value.clipPath, value.sourceVideo, value.rawFootage, value.url]
      .filter(Boolean)
      .map((item) => String(item));
  }
  return [];
}

function expandMediaPath(pathValue) {
  const path = String(pathValue || "").trim();
  if (!path || /^https?:\/\//i.test(path)) {
    return [{ path, exists: false, kind: path ? "remote-url" : "missing" }];
  }
  const abs = resolve(ROOT, path);
  if (!existsSync(abs)) return [{ path, absolutePath: abs, exists: false, kind: "missing-local-path" }];
  const stat = statSync(abs);
  if (stat.isDirectory()) {
    const files = readdirSync(abs)
      .filter((file) => /\.(mp4|mov|mkv|webm|m4v|avi)$/i.test(file))
      .map((file) => {
        const filePath = join(abs, file);
        return {
          path: relative(ROOT, filePath),
          absolutePath: filePath,
          exists: true,
          kind: "local-video-file",
          bytes: statSync(filePath).size,
        };
      });
    return files.length ? files : [{ path, absolutePath: abs, exists: true, kind: "empty-local-directory" }];
  }
  return [{
    path,
    absolutePath: abs,
    exists: true,
    kind: "local-file",
    bytes: stat.size,
  }];
}

function rawFootageInventoryFromBrief(brief) {
  const scenePaths = (Array.isArray(brief.scenes) ? brief.scenes : [])
    .flatMap((scene) => mediaPathsFromValue([scene.sourceVideo, scene.rawFootage, scene.clipPath]).map((path) => ({
      path,
      sceneId: scene.id || scene.label || "scene",
    })));
  const topLevelPaths = mediaPathsFromValue([
    brief.rawFootageDir,
    brief.rawFootage,
    brief.sourceVideoPath,
    brief.sourceVideoDir,
  ]).map((path) => ({ path, sceneId: null }));
  const entries = [...topLevelPaths, ...scenePaths].flatMap((source, index) =>
    expandMediaPath(source.path).map((expanded, expandedIndex) => ({
      clipId: `clip-${String(index + 1).padStart(2, "0")}-${expandedIndex + 1}`,
      sceneId: source.sceneId,
      source: source.path,
      ...expanded,
      rightsStatus: brief.rights?.externalMedia && brief.rights.externalMedia !== "none" ? "declared-by-brief" : "needs-rights-review",
    })),
  );
  return {
    schemaVersion: 1,
    stage: "pre-render-raw-footage-inventory",
    sourceReference: "references/external-capability-fusion.md",
    status: entries.some((entry) => entry.exists) ? "inventory-ready" : "awaiting-authorized-source-files",
    rightsPolicy: "Only user-authorized or clearly licensed footage may enter the edit path.",
    entries,
  };
}

