        reusableSegmentTimings = buildSegmentTimings({ segments, filesBySegment, rawDuration: narrationDuration });
        reusableSegmentTimingSource = segments.some((segment) => segment.cueIndex)
          ? "actual_subtitle_cue_tts_segments"
          : "actual_per_frame_tts_segments";
