  const ipDiagramCreatorVendorUsage = readJsonIfExists(join(out, "workflow", "ip-diagram-creator-vendor-usage.json")) || {};
  const personalIpAssetRegistry = readJsonIfExists(join(out, "workflow", "personal-ip-asset-registry.json")) || {};
  const ipDiagramCreatorNativeJobs = readJsonIfExists(join(out, "workflow", "ip-diagram-creator-native-jobs.json")) || {};
  const ipDiagramLayoutAudit = readJsonIfExists(join(out, "workflow", "ip-diagram-layout-audit.json")) || {};
  const nativePageProvenanceAudit = readJsonIfExists(join(out, "workflow", "native-page-provenance-audit.json")) || {};
  let skillUsageAccuracyAudit = readJsonIfExists(join(out, "workflow", "skill-usage-accuracy-audit.json")) || {};
  const motionSelection = readJsonIfExists(join(out, "workflow", "motion-template-selection.json")) || {};
  const visualAssetManifest = readJsonIfExists(join(out, "workflow", "visual-asset-manifest.json")) || {};
  const visualRelevanceAudit = readJsonIfExists(join(out, "workflow", "visual-relevance-audit.json")) || {};
  const imageGenerationStrategy = readJsonIfExists(join(out, "workflow", "image-generation-strategy.json")) || {};
  const visualRhythmPlan = readJsonIfExists(join(out, "workflow", "visual-rhythm-plan.json")) || {};
  const shortFormHookPlan = readJsonIfExists(join(out, "workflow", "short-form-hook-plan.json")) || {};
  const typographyMotionPlan = readJsonIfExists(join(out, "workflow", "typography-motion-plan.json")) || {};
  const captionStylePlan = readJsonIfExists(join(out, "workflow", "caption-style-plan.json")) || {};
  const themeReadabilityAudit = readJsonIfExists(join(out, "workflow", "theme-readability-audit.json")) || {};
  const colorSystemPlan = readJsonIfExists(join(out, "workflow", "color-system-plan.json")) || designPlan.colorSystemPlan || {};
  const qualityContract = readJsonIfExists(join(out, "workflow", "quality-consistency-contract.json")) || {};
  const generationModeContract = readJsonIfExists(join(out, "workflow", "generation-mode-contract.json")) || {};
  const runtimeConfig = readJsonIfExists(join(out, "workflow", "runtime-config.json")) || {};
  const pluginRoutingContract = readJsonIfExists(join(out, "workflow", "plugin-routing-contract.json")) || {};
  const externalCapabilityFusionPlan = readJsonIfExists(join(out, "workflow", "external-capability-fusion-plan.json")) || {};
  const dataSourcePlan = readJsonIfExists(join(out, "workflow", "data-source-plan.json")) || {};
  const dataSeries = readJsonIfExists(join(out, "workflow", "data-series.json")) || {};
  const dataMotionPlan = readJsonIfExists(join(out, "workflow", "data-motion-plan.json")) || {};
  const rawFootageInventory = readJsonIfExists(join(out, "workflow", "raw-footage-inventory.json")) || {};
  const freeStockMaterialPlan = readJsonIfExists(join(out, "workflow", "free-stock-material-plan.json")) || {};
  const freeStockAssetLedger = readJsonIfExists(join(out, "workflow", "free-stock-asset-ledger.json")) || {};
  const rawTranscriptIndex = readJsonIfExists(join(out, "workflow", "raw-transcript-index.json")) || {};
  const wordBoundaryMap = readJsonIfExists(join(out, "workflow", "word-boundary-map.json")) || {};
  const editDecisionList = readJsonIfExists(join(out, "workflow", "edit-decision-list.json")) || {};
  const cutBoundaryQc = readJsonIfExists(join(out, "workflow", "cut-boundary-qc.json")) || {};
  const sourceMediaNormalizationPlan = readJsonIfExists(join(out, "workflow", "source-media-normalization-plan.json")) || {};
  const productionPlan = readJsonIfExists(join(out, "workflow", "production-plan.json")) || {};
  const pageDecisionContract = readJsonIfExists(join(out, "workflow", "page-decision-contract.json")) || {};
  const retentionStructureContract = readJsonIfExists(join(out, "workflow", "retention-structure-contract.json")) || {};
  const materialCandidatePool = readJsonIfExists(join(out, "workflow", "material-candidate-pool.json")) || {};
  const mediaRoutingPlan = readJsonIfExists(join(out, "workflow", "media-routing-plan.json")) || {};
  const motionGrammarPlan = readJsonIfExists(join(out, "workflow", "motion-grammar-plan.json")) || {};
  const motionStylePlan = readJsonIfExists(join(out, "workflow", "motion-style-plan.json")) || {};
  const motionStyleTemplateSelection = readJsonIfExists(join(out, "workflow", "motion-style-template-selection.json")) || {};
  const galaceanEffectsPlan = readJsonIfExists(join(out, "workflow", "galacean-effects-plan.json")) || {};
  const coverImage2Qc = readJsonIfExists(join(out, "workflow", "cover-image2-qc.json")) || {};
  const coverSizeSelection = readJsonIfExists(join(out, "workflow", "cover-size-selection.json")) || {};
  const imageSource = brief.imageSource || designPlan.imageSource || visualAssetManifest.imageSource || imageGenerationStrategy.selectedImageSource || "image2-dryrun";
  const contentCoverage = readJsonIfExists(join(out, "workflow", "content-coverage.json")) || {};
  const frameLayoutOverlapAudit = runFrameLayoutOverlapAudit({ out, renderer });
  const coverIntroSeconds = Number(voiceManifest.timing?.coverIntroSeconds || renderManifest.openingCoverSeconds || 0);
